styles.css:
position: relative;
overflow: hidden;

& .ls-card-cluster__content {
	flex: 1 1 auto;
	display: flex;
	flex-direction: column;
	gap: var(--wp--preset--spacing--10);
}

& .ls-card-cluster__tags {
	border-top: 1px solid var(--wp--custom--color--border--card);
}

& .ls-cluster-tag {
	position: relative;
}

& .ls-cluster-tag__link::before {
	content: "";
	position: absolute;
	inset: 0;
}

& .ls-cluster-tag__link:focus-visible {
	outline: 2px solid var(--wp--custom--color--focus--ring);
	outline-offset: 2px;
}
